PYTHONPATH=. python3 - <<'EOF'
import ast, inspect, more_itertools as mi, more_itertools.more as M, more_itertools.recipes as Rc, re
for mod,stub in [(M,'more_itertools/more.pyi'),(Rc,'more_itertools/recipes.pyi')]:
    # __all__ consistency
    for n in mod.__all__:
        if not hasattr(mod,n): print("missing in module", mod.__name__, n)
    defined=[n for n,o in vars(mod).items() if not n.startswith('_') and getattr(o,'__module__',None)==mod.__name__]
    print(mod.__name__, "not in __all__:", [n for n in defined if n not in mod.__all__])
    t=ast.parse(open(stub).read())
    sig={}
    for n in t.body:
        if isinstance(n,(ast.FunctionDef,)):
            sig.setdefault(n.name,[]).append([a.arg for a in n.args.posonlyargs+n.args.args]+[a.arg for a in n.args.kwonlyargs])
    for name,lst in sig.items():
        o=getattr(mod,name,None)
        if o is None: print("stub-only",name); continue
        try: rp=list(inspect.signature(o).parameters)
        except Exception: continue
        rp=[p for p in rp if inspect.signature(o).parameters[p].kind not in (2,4)]
        if not any(s==rp for s in lst): print("sig mismatch",name,rp,lst)
# doctests in README and docs
import doctest
for f in ['README.rst','docs/api.rst']:
    try: print(f, doctest.testfile(f, module_relative=False, globs=vars(mi).copy(), optionflags=doctest.ELLIPSIS, report=False))
    except Exception as e: print(f,e)
api=open('docs/api.rst').read()
print("undocumented:", [n for n in dir(mi) if not n.startswith('_') and n not in api and callable(getattr(mi,n))])
EOF

